ul.li:
foaf:Person : foaf:name, foaf:nick, foaf:age,
				foaf:mbox, ex:ville, foaf:topic_interest, et
				foaf:knows vers les personnes qu'elle connaît ;

exemples.exemple:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?nom ?age
WHERE {
  ?p a foaf:Person ;
     foaf:name ?nom ;
     foaf:age ?age .
}
ORDER BY ?age

PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?nom ?age
WHERE {
  ?p a foaf:Person ; foaf:name ?nom .
  OPTIONAL { ?p foaf:age ?age }
}

PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ex:   <http://example.org/amis/>
INSERT DATA { ex:gabriel foaf:knows ex:alice }

PREFIX foaf: <http://xmlns.com/foaf/0.1/>
DELETE { ?p foaf:age ?age }
INSERT { ?p foaf:age ?nouvel }
WHERE  { ?p foaf:age ?age . BIND (?age + 1 AS ?nouvel) }
